-- Phase 2 M4: lead import jobs and per-row results. Part 1 generated by `prisma migrate diff`
-- from schema.prisma; part 2 (below the marker) is hand-written. Reviewed design:
-- docs/PHASE-2-M4-PROPOSAL.md §B (approved 2026-10-23), with the changes listed in
-- docs/PHASE-2-M4-REPORT.md ("0005 security review").

-- CreateTable
CREATE TABLE "import_job" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "org_id" UUID NOT NULL,
    "created_by" UUID NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'AWAITING_UPLOAD',
    "file_type" TEXT NOT NULL,
    "content_type" TEXT NOT NULL,
    "original_filename" TEXT NOT NULL,
    "byte_size" BIGINT NOT NULL,
    "storage_key" TEXT NOT NULL,
    "sha256" BYTEA,
    "sheet_names" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "sheet_name" TEXT,
    "headers" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "mapping" JSONB,
    "default_source_id" UUID,
    "duplicate_policy" TEXT NOT NULL DEFAULT 'ATTACH',
    "assignment" JSONB NOT NULL DEFAULT '{"mode":"none"}',
    "dry_run" BOOLEAN NOT NULL DEFAULT false,
    "attested_at" TIMESTAMPTZ(6),
    "attestation_version" TEXT,
    "hash_warning_ack_at" TIMESTAMPTZ(6),
    "duplicate_of_job_id" UUID,
    "validation_attempt" INTEGER NOT NULL DEFAULT 0,
    "next_row" INTEGER NOT NULL DEFAULT 0,
    "rows_total" INTEGER NOT NULL DEFAULT 0,
    "rows_empty" INTEGER NOT NULL DEFAULT 0,
    "rows_valid" INTEGER NOT NULL DEFAULT 0,
    "rows_invalid" INTEGER NOT NULL DEFAULT 0,
    "rows_duplicate_in_file" INTEGER NOT NULL DEFAULT 0,
    "rows_created" INTEGER NOT NULL DEFAULT 0,
    "rows_attached" INTEGER NOT NULL DEFAULT 0,
    "rows_skipped" INTEGER NOT NULL DEFAULT 0,
    "rows_failed" INTEGER NOT NULL DEFAULT 0,
    "error_code" TEXT,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "upload_expires_at" TIMESTAMPTZ(6) NOT NULL DEFAULT (CURRENT_TIMESTAMP + '02:00:00'::interval),
    "uploaded_at" TIMESTAMPTZ(6),
    "validated_at" TIMESTAMPTZ(6),
    "started_at" TIMESTAMPTZ(6),
    "finished_at" TIMESTAMPTZ(6),
    "cancel_requested_at" TIMESTAMPTZ(6),
    "purge_file_after" TIMESTAMPTZ(6) NOT NULL DEFAULT (CURRENT_TIMESTAMP + '03:00:00'::interval),
    "file_deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "import_job_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "import_row_result" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "org_id" UUID NOT NULL,
    "import_job_id" UUID NOT NULL,
    "phase" TEXT NOT NULL,
    "attempt" INTEGER NOT NULL,
    "row_number" INTEGER NOT NULL,
    "outcome" TEXT NOT NULL,
    "field" TEXT,
    "code" TEXT NOT NULL,
    "related_row" INTEGER,
    "lead_id" UUID,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "import_row_result_pkey" PRIMARY KEY ("id")
);

