-- ===========================================================================
-- Hand-written part (prisma/README.md). Phase 2 M4: lead import jobs. Runs as crm_migrator.
-- New tables, one trigger and one definer function only: no existing table, policy, grant
-- or role changes.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. Integrity
-- ---------------------------------------------------------------------------
ALTER TABLE import_job
  ALTER COLUMN sheet_names SET NOT NULL,
  ALTER COLUMN headers SET NOT NULL;

ALTER TABLE import_job
  ADD CONSTRAINT import_job_status CHECK (status IN ('AWAITING_UPLOAD', 'UPLOADED', 'ANALYSING',
    'NEEDS_MAPPING', 'VALIDATING', 'READY', 'IMPORTING', 'PAUSED', 'COMPLETED',
    'COMPLETED_WITH_ERRORS', 'FAILED', 'CANCELLED', 'EXPIRED')),
  ADD CONSTRAINT import_job_file_type CHECK (file_type IN ('csv', 'xlsx')),
  ADD CONSTRAINT import_job_content_type CHECK (content_type IN ('text/csv',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')),
  ADD CONSTRAINT import_job_byte_size CHECK (byte_size BETWEEN 1 AND 52428800),
  ADD CONSTRAINT import_job_filename CHECK (length(original_filename) BETWEEN 1 AND 200
    AND original_filename !~ '[/\\[:cntrl:]]'),
  -- The object key is namespaced by this row's own org and id; the database refuses any other.
  ADD CONSTRAINT import_job_storage_key CHECK (storage_key ~ ('^orgs/' || org_id::text ||
    '/imports/' || id::text || '/[0-9a-f]{32}\.(csv|xlsx)$')),
  ADD CONSTRAINT import_job_sha256 CHECK (sha256 IS NULL OR length(sha256) = 32),
  ADD CONSTRAINT import_job_lists CHECK (cardinality(sheet_names) <= 20
    AND cardinality(headers) <= 100),
  ADD CONSTRAINT import_job_sheet_name CHECK (sheet_name IS NULL OR length(sheet_name) <= 100),
  ADD CONSTRAINT import_job_mapping CHECK (mapping IS NULL OR jsonb_typeof(mapping) = 'object'),
  ADD CONSTRAINT import_job_assignment CHECK (jsonb_typeof(assignment) = 'object'
    AND assignment->>'mode' IN ('none', 'target', 'round_robin')),
  ADD CONSTRAINT import_job_duplicate_policy CHECK (duplicate_policy IN ('ATTACH', 'SKIP')),
  ADD CONSTRAINT import_job_counters CHECK (least(rows_total, rows_empty, rows_valid, rows_invalid,
    rows_duplicate_in_file, rows_created, rows_attached, rows_skipped, rows_failed, next_row,
    validation_attempt) >= 0 AND rows_total <= 100000 AND next_row <= rows_total),
  ADD CONSTRAINT import_job_attestation_version CHECK (attestation_version IS NULL
    OR attestation_version ~ '^[A-Za-z0-9._-]{1,20}$'),
  -- Leads are written only by an attested, non-dry-run import; a dry run never writes leads.
  ADD CONSTRAINT import_job_attested CHECK (status NOT IN ('IMPORTING', 'PAUSED')
    OR (attested_at IS NOT NULL AND NOT dry_run)),
  ADD CONSTRAINT import_job_completed CHECK (status NOT IN ('COMPLETED', 'COMPLETED_WITH_ERRORS')
    OR dry_run OR attested_at IS NOT NULL),
  ADD CONSTRAINT import_job_dry_run_writes_nothing CHECK (NOT dry_run
    OR (rows_created = 0 AND rows_attached = 0 AND next_row = 0)),
  ADD CONSTRAINT import_job_terminal_finished CHECK (status NOT IN ('COMPLETED',
    'COMPLETED_WITH_ERRORS', 'FAILED', 'CANCELLED', 'EXPIRED') OR finished_at IS NOT NULL),
  ADD CONSTRAINT import_job_error_code CHECK (error_code IS NULL
    OR error_code ~ '^[A-Z0-9_]{1,50}$');
-- At most one import writing leads per org (threat model). A paused import keeps its slot, so
-- it cannot interleave with a newer one when it resumes.
CREATE UNIQUE INDEX import_job_one_running_uq ON import_job (org_id)
  WHERE status IN ('IMPORTING', 'PAUSED');
-- Same-file warning (FR-049) and the cleanup sweep.
CREATE INDEX import_job_hash_idx ON import_job (org_id, sha256, created_at) WHERE sha256 IS NOT NULL;
CREATE INDEX import_job_purge_idx ON import_job (purge_file_after) WHERE file_deleted_at IS NULL;

ALTER TABLE import_row_result
  ADD CONSTRAINT import_row_result_phase CHECK (phase IN ('VALIDATE', 'IMPORT')),
  ADD CONSTRAINT import_row_result_outcome CHECK (outcome IN ('INVALID', 'DUPLICATE_IN_FILE',
    'DUPLICATE_ATTACHED', 'DUPLICATE_SKIPPED', 'FAILED')),
  ADD CONSTRAINT import_row_result_codes CHECK (code ~ '^[A-Z0-9_]{1,50}$'
    AND (field IS NULL OR field ~ '^[A-Za-z_]{1,50}$')),
  ADD CONSTRAINT import_row_result_row CHECK (row_number BETWEEN 1 AND 1000001
    AND (related_row IS NULL OR related_row BETWEEN 1 AND 1000001) AND attempt >= 0);
-- A retried batch or validation pass never duplicates a result.
CREATE UNIQUE INDEX import_row_result_uq ON import_row_result
  (import_job_id, phase, attempt, row_number, outcome, coalesce(field, ''), code);

-- ---------------------------------------------------------------------------
-- 2. State machine (the schema's first trigger). Finished jobs are frozen; status follows the
--    listed transitions (FAILED / CANCELLED from any unfinished state); the import's settings
--    cannot change while it is writing leads; the resume cursor only moves forward.
-- ---------------------------------------------------------------------------
CREATE FUNCTION app.import_job_guard() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF OLD.status IN ('COMPLETED', 'COMPLETED_WITH_ERRORS', 'FAILED', 'CANCELLED', 'EXPIRED') THEN
    -- Only the cleanup marker may change on a finished job.
    IF (to_jsonb(NEW) - ARRAY['file_deleted_at', 'updated_at', 'version'])
       IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['file_deleted_at', 'updated_at', 'version']) THEN
      RAISE EXCEPTION 'import job % is finished', OLD.id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status NOT IN ('FAILED', 'CANCELLED')
     AND (OLD.status, NEW.status) NOT IN (
       ('AWAITING_UPLOAD', 'UPLOADED'), ('UPLOADED', 'ANALYSING'),
       ('ANALYSING', 'NEEDS_MAPPING'), ('NEEDS_MAPPING', 'ANALYSING'),
       ('NEEDS_MAPPING', 'VALIDATING'), ('VALIDATING', 'READY'),
       ('READY', 'VALIDATING'), ('READY', 'NEEDS_MAPPING'), ('READY', 'IMPORTING'),
       ('READY', 'COMPLETED'),
       ('IMPORTING', 'COMPLETED'), ('IMPORTING', 'COMPLETED_WITH_ERRORS'),
       ('IMPORTING', 'PAUSED'), ('PAUSED', 'IMPORTING'),
       ('AWAITING_UPLOAD', 'EXPIRED'), ('UPLOADED', 'EXPIRED'), ('NEEDS_MAPPING', 'EXPIRED'),
       ('READY', 'EXPIRED'), ('PAUSED', 'EXPIRED')) THEN
    RAISE EXCEPTION 'import job % cannot go from % to %', OLD.id, OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;

  -- READY -> COMPLETED is the end of a dry run only.
  IF OLD.status = 'READY' AND NEW.status = 'COMPLETED' AND NOT NEW.dry_run THEN
    RAISE EXCEPTION 'import job % has not imported its rows', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.status IN ('IMPORTING', 'PAUSED')
     AND (NEW.sheet_name, NEW.headers, NEW.mapping, NEW.default_source_id, NEW.duplicate_policy,
          NEW.assignment, NEW.dry_run, NEW.attested_at, NEW.attestation_version, NEW.sha256,
          NEW.validation_attempt)
         IS DISTINCT FROM
         (OLD.sheet_name, OLD.headers, OLD.mapping, OLD.default_source_id, OLD.duplicate_policy,
          OLD.assignment, OLD.dry_run, OLD.attested_at, OLD.attestation_version, OLD.sha256,
          OLD.validation_attempt) THEN
    RAISE EXCEPTION 'import job % settings are fixed while importing', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.next_row < OLD.next_row THEN
    RAISE EXCEPTION 'import job % cursor cannot move back', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION app.import_job_guard() FROM PUBLIC;
CREATE TRIGGER import_job_guard BEFORE UPDATE ON import_job
  FOR EACH ROW EXECUTE FUNCTION app.import_job_guard();

-- ---------------------------------------------------------------------------
-- 3. RLS: ENABLE + FORCE, maintenance, tenant isolation (same text as 0002–0004)
-- ---------------------------------------------------------------------------
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['import_job', 'import_row_result'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY maintenance ON %I FOR ALL TO crm_migrator USING (true) WITH CHECK (true)', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO crm_app '
      'USING (org_id = (SELECT app.current_org_id())) '
      'WITH CHECK (org_id = (SELECT app.current_org_id()))', t);
  END LOOP;
END $$;

-- RESTRICTIVE: they narrow tenant_isolation, never widen it.
-- A job is created by the session user, at the transaction time, in its first state, with the
-- database's own upload and cleanup deadlines (or earlier).
CREATE POLICY actor_is_session_user ON import_job AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (created_by = (SELECT app.current_user_id())
              AND status = 'AWAITING_UPLOAD' AND created_at = now()
              AND upload_expires_at <= now() + interval '2 hours'
              AND purge_file_after <= now() + interval '3 hours'
              AND attested_at IS NULL AND next_row = 0 AND file_deleted_at IS NULL);
-- Stored files are never kept longer than 24 h past the last update (runbook §6).
CREATE POLICY bounded_retention ON import_job AS RESTRICTIVE FOR UPDATE TO crm_app
  USING (true)
  WITH CHECK (purge_file_after <= now() + interval '24 hours');
-- Results are written only while their job is validating or importing, for its current pass.
CREATE POLICY job_is_active ON import_row_result AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (EXISTS (SELECT 1 FROM import_job j
                      WHERE j.id = import_row_result.import_job_id
                        AND j.org_id = import_row_result.org_id
                        AND j.status IN ('VALIDATING', 'IMPORTING')
                        AND j.validation_attempt = import_row_result.attempt));

-- ---------------------------------------------------------------------------
-- 4. crm_app grants (minimum). No DELETE. crm_auth / crm_platform get nothing.
--    Identity, tenant, uploader, storage key, file type/size/name, created_at and the upload
--    deadline are never updatable.
-- ---------------------------------------------------------------------------
GRANT SELECT, INSERT ON import_job, import_row_result TO crm_app;
GRANT UPDATE (status, sha256, sheet_names, sheet_name, headers, mapping, default_source_id,
  duplicate_policy, assignment, dry_run, attested_at, attestation_version, hash_warning_ack_at,
  duplicate_of_job_id, validation_attempt, next_row, rows_total, rows_empty, rows_valid,
  rows_invalid, rows_duplicate_in_file, rows_created, rows_attached, rows_skipped, rows_failed,
  error_code, version, updated_at, uploaded_at, validated_at, started_at, finished_at,
  cancel_requested_at, purge_file_after, file_deleted_at) ON import_job TO crm_app;

-- ---------------------------------------------------------------------------
-- 5. Cleanup lookup across orgs: definer-owned, column-limited, ids and keys only (no PII).
--    Callable ONLY by crm_cleanup: a dedicated LOGIN role used by the worker's cleanup sweep
--    through its own connection (CLEANUP_DATABASE_URL). crm_cleanup is created by role
--    provisioning, not here (crm_migrator cannot create roles): NOSUPERUSER, NOBYPASSRLS,
--    NOINHERIT, no memberships, no table or column grants anywhere. This migration fails if the
--    role does not exist. The worker deletes an object only if its key belongs to the returned
--    org and job, then marks the row inside that org's tenant transaction (crm_app).
-- ---------------------------------------------------------------------------
CREATE POLICY definer_lookup ON import_job FOR SELECT TO crm_definer USING (true);
GRANT SELECT (id, org_id, storage_key, purge_file_after, file_deleted_at) ON import_job TO crm_definer;

CREATE FUNCTION app.import_files_due(p_limit integer)
  RETURNS TABLE (org_id uuid, import_job_id uuid, storage_key text)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT j.org_id, j.id, j.storage_key
    FROM public.import_job j
    WHERE j.file_deleted_at IS NULL AND j.purge_file_after <= now()
    ORDER BY j.purge_file_after
    LIMIT least(greatest(p_limit, 0), 500)
  $$;
ALTER FUNCTION app.import_files_due(integer) OWNER TO crm_definer;
REVOKE ALL ON FUNCTION app.import_files_due(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION app.import_files_due(integer) FROM crm_app, crm_auth, crm_platform;
-- Name resolution in schema app, and this one function. Nothing else.
GRANT USAGE ON SCHEMA app TO crm_cleanup;
GRANT EXECUTE ON FUNCTION app.import_files_due(integer) TO crm_cleanup;
